// Revenue conversion fix: ensure paidEvents increments on successful checkout
// This module intercepts checkout completion and triggers revenue event

const revenueAutopilot = require('./revenue-autopilot');

module.exports = function(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function(body) {
    if (req.path === '/api/checkout/complete' && res.statusCode === 200) {
      // Trigger revenue event
      revenueAutopilot.recordEvent('paid', { amount: body.amount || 0, currency: 'USD' });
    }
    return originalJson(body);
  };
  next();
};
